import test from'node:test';import assert from'node:assert/strict';import{createHash}from'node:crypto';import{execFileSync}from'node:child_process';import{persistPostWriteHandoff,validatePostWriteHandoff}from'./post-write-job-handoff.mjs';
const sha=(x,a='sha256')=>createHash(a).update(x).digest('hex');
// Test keys are generated by the test command, never user key material.
const key=process.env.ZZ_TEST_AGE_KEY,recipient=key?execFileSync('age-keygen',['-y',key],{encoding:'utf8'}).trim():null;
test('real age encryption -> bounded private Git write -> exact remote readback -> decrypt',{skip:!key},async t=>{
 const p={repository_id:'999001',owner:'ZZ-owner',repo:'ZZ-private',branch:'ZZ-main',parent_commit:'a'.repeat(40),path:'ZZ-prewrite.age',recipient:sha(recipient),operation_binding:'b'.repeat(64),run_id:'999002',stage:'readback',existing_total_bytes:0};
 const c={mode:'unreleased_protected_job_evidence',production_enabled:false,recipient,storage:p},raw=JSON.stringify(c),env={FATHER_EVIDENCE_RELEASE_JSON:raw,FATHER_EVIDENCE_RELEASE_SHA256:sha(raw),PRIVATE_GIT_CREDENTIAL:'ZZsynthetic',GITHUB_RUN_ATTEMPT:'1',GITHUB_REF:'refs/heads/master',GITHUB_EVENT_NAME:'workflow_dispatch',GITHUB_RUN_ID:p.run_id};
 const evidence={schema_version:1,mode:'private_post_write_evidence',binding:{owner:'profile-999001',connection:'ZZ-connection',plan:p.operation_binding,payload:'c'.repeat(64),artifact:'d'.repeat(64),policy:'e'.repeat(64)},acknowledgment:{id:'profile-999003',first_name:'ZZFather'},profile:{id:'profile-999003',public:false},family:{focus:{id:'profile-999001'}},union:{id:'union-999004'}};const resultBody={phase:'consumed_readback_consistent_evidence_pending',created_id:'profile-999003',private_evidence:evidence,retry_allowed:false,post_write_evidence_durable:false,production_enabled:false};env.FATHER_POSTWRITE_BINDING_JSON=JSON.stringify(evidence.binding);env.FATHER_POSTWRITE_BINDING_SHA256=sha(env.FATHER_POSTWRITE_BINDING_JSON);const plaintext=Buffer.from(JSON.stringify({result_phase:resultBody.phase,created_id:resultBody.created_id,evidence}));let bytes,blob,entry,n=0;const root='https://api.github.com/repos/ZZ-owner/ZZ-private',tree='c'.repeat(40),commit='d'.repeat(40),old='e'.repeat(40);const ref=x=>({ref:'refs/heads/ZZ-main',object:{type:'commit',sha:x}}),co={sha:commit,tree:{sha:tree},parents:[{sha:p.parent_commit}]};const events=[];
 t.mock.method(globalThis,'fetch',async(url,o)=>{n++;assert.equal(o.headers.Authorization,'Bearer ZZsynthetic');assert.equal(o.redirect,'manual');let body;if(o.method==='POST'&&url===root+'/git/blobs'){bytes=Buffer.from(JSON.parse(o.body).content,'base64');assert.ok(!bytes.includes(plaintext));blob=sha(Buffer.concat([Buffer.from('blob '+bytes.length+'\0'),bytes]),'sha1');entry={path:p.path,mode:'100644',type:'blob',sha:blob};body={sha:blob};}
 else if(url==='https://api.github.com/repositories/999001')body={id:999001,private:true,full_name:'ZZ-owner/ZZ-private'};
 else if(url===root+'/git/ref/heads/ZZ-main')body=ref(n===2?p.parent_commit:commit);
 else if(url===root+'/git/commits/'+p.parent_commit)body={sha:p.parent_commit,tree:{sha:old}};
 else if(url===root+'/git/trees/'+old)body={sha:old,truncated:false,tree:[]};
 else if(url===root+'/git/trees'&&o.method==='POST')body={sha:tree,truncated:false,tree:[entry]};
 else if(url===root+'/git/commits'||url===root+'/git/commits/'+commit)body=co;
 else if(url===root+'/git/refs/heads/ZZ-main'){assert.equal(JSON.parse(o.body).force,false);body=ref(commit);}
 else if(url===root+'/git/blobs/'+blob)body={sha:blob,encoding:'base64',size:bytes.length,content:bytes.toString('base64')};
 else throw Error('unexpected route');return Response.json(body,{status:o.method==='POST'?201:200});});
 const result=await persistPostWriteHandoff(env,resultBody,x=>events.push(x));assert.equal(n,11);assert.equal(result.descriptor.commit,commit);assert.equal(result.intent_verified,false);assert.equal(events.length,4);assert.deepEqual(execFileSync('age',['-d','-i',key],{input:bytes}),plaintext);
});
test('malformed service result stops before age or HTTP',async()=>{await assert.rejects(persistPostWriteHandoff({}, {phase:'VERIFIED'},()=>{}));});

function fixture(){
 const binding={owner:'profile-999001',connection:'ZZ-connection',plan:'b'.repeat(64),payload:'c'.repeat(64),artifact:'d'.repeat(64),policy:'e'.repeat(64)},raw=JSON.stringify(binding);
 return {env:{FATHER_POSTWRITE_BINDING_JSON:raw,FATHER_POSTWRITE_BINDING_SHA256:sha(raw)},result:{phase:'consumed_readback_consistent_evidence_pending',created_id:'profile-999003',private_evidence:{schema_version:1,mode:'private_post_write_evidence',binding,acknowledgment:{id:'profile-999003'},profile:{id:'profile-999003'},family:{focus:{id:'profile-999001'}},union:{id:'union-999004'}},retry_allowed:false,post_write_evidence_durable:false,production_enabled:false}};
}
test('full fixed binding and exact schemas reject every identity mutation before encryption',()=>{
 const good=fixture();assert.deepEqual(validatePostWriteHandoff(good.env,good.result),good.result.private_evidence);
 for(const field of ['owner','connection','plan','payload','artifact','policy']){
  const {env,result}=fixture();result.private_evidence.binding[field]=field==='owner'?'profile-999005':field==='connection'?'ZZ-other':'f'.repeat(64);assert.throws(()=>validatePostWriteHandoff(env,result));
 }
 for(const mutate of [
  x=>x.result.extra='ZZ-extra',x=>delete x.result.retry_allowed,
  x=>x.result.private_evidence.extra='ZZ-extra',x=>delete x.result.private_evidence.union,
  x=>x.result.private_evidence.binding.extra='ZZ-extra',x=>delete x.result.private_evidence.binding.owner,
  x=>x.env.FATHER_POSTWRITE_BINDING_SHA256='0'.repeat(64),x=>delete x.env.FATHER_POSTWRITE_BINDING_JSON,
  x=>x.result.created_id='profile-999001',x=>x.result.created_id=null,
  x=>x.result.private_evidence.acknowledgment.id='profile-999005',x=>x.result.private_evidence.profile=null,
  x=>x.result.private_evidence.family.focus.id='profile-999005',x=>x.result.private_evidence.union.id='profile-999004',
  x=>x.result.private_evidence.profile=[],x=>x.result.phase='verified',
 ]){const x=fixture();mutate(x);assert.throws(()=>validatePostWriteHandoff(x.env,x.result));}
});
test('uncertain evidence permits no-ID partial responses without promoting them',()=>{
 const {env,result}=fixture();result.phase='consumed_uncertain';result.created_id=null;
 for(const k of ['acknowledgment','profile','family','union'])result.private_evidence[k]=null;
 assert.equal(validatePostWriteHandoff(env,result).profile,null);
});
